<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class AlumniSet extends Model{protected $table='alumni_sets';protected $fillable=['year','coordinator_id','description','whatsapp_url','telegram_url','active'];protected function casts():array{return ['active'=>'boolean'];}public function members(){return $this->hasMany(User::class,'graduating_year','year');}public function coordinator(){return $this->belongsTo(User::class,'coordinator_id');}public function administrators(){return $this->belongsToMany(User::class,'alumni_set_admins')->withPivot(['is_primary','active','assigned_by'])->withTimestamps()->wherePivot('active',true);}}
